import React, { useState } from 'react';
import './Tabs.css'; // Ensure your CSS is imported

const TabData = [
  { id: 'tab-1', title: 'Product', content: 'The Sweep + Slide is an indoor dog toy with a sleek base designed to glide across any floor. Not only does this toy stimulate your dog\'s natural chase instincts, but it also sweeps away floor dust and grime with a replaceable sweeper bottom cover.' },
  { id: 'tab-2', title: 'Options', content: 'Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor' },
  { id: 'tab-3', title: 'Shipping', content: 'Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis' },
  { id: 'tab-4', title: 'Published', content: 'Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.' }
];

const Tabs = () => {
  const [activeTab, setActiveTab] = useState('tab-1');

  return (
    <div className="wrapper">
      {/* <div className="title">
        CSS Tabs
        <div className="line"></div>
      </div> */}
      <div className="container">
        <div className="card tabs">
          {TabData.map((tab, index) => (
            <>
              <input id={tab.id} type="radio" className="tab tab-selector" 
                     checked={activeTab === tab.id} onChange={() => setActiveTab(tab.id)} 
                     name="tab" />
              <label htmlFor={tab.id} className={`tab tab-${tab.title.toLowerCase()}`}>{tab.title}</label>
            </>
          ))}
          <div className="tabsShadow"></div>
          <div className="glider"></div>
          <section className="content">
            {TabData.map(tab => (
              <div className={`item ${activeTab === tab.id ? '' : 'hidden'}`} id={`content-${tab.id.slice(-1)}`}>
                <h2 className={`tab-title tab-${tab.title.toLowerCase()}`}>{tab.title}</h2>
                <p>
                  <span className="numit">{tab.id.slice(-1)}</span> {tab.content}
                </p>
              </div>
            ))}
          </section>
        </div>
      </div>
    </div>
  );
};

export default Tabs;
